#!/usr/bin/env node
/**
 * PostToolUse advisory (SPEC G-18, "teeth in hooks").
 *
 * Skills load probabilistically. This hook makes the trigger deterministic:
 * when a file is edited that a standard governs, it does not merely *name*
 * the skill — it emits the skill's own checklist, so the procedure arrives
 * in context whether or not anyone chose to load it. Naming a skill still
 * leaves the loading to judgement, and three rounds of verification found
 * judgement is exactly what forgets.
 *
 * It never blocks; it reminds at the exact moment of relevance. What it
 * cannot do is force the checklist to be followed — that is the Stop gate's
 * job, and the artifacts it requires.
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { writtenPaths } from "../lib/written-paths.mjs";

/**
 * A skill's checklist: its headline rules, not the whole file. Enough to act
 * on without flooding the context of a one-line edit.
 */
function checklist(skill) {
  const root = process.env.CLAUDE_PROJECT_DIR || process.cwd();
  const path = join(root, ".claude", "skills", skill, "SKILL.md");
  let text;
  try {
    text = readFileSync(path, "utf8");
  } catch {
    // Never silent. A missing skill used to produce a note with the block
    // simply absent, so the standard a session was told to follow could
    // vanish without a word (enforcement-layer verification, gate 4).
    return `\n   ${skill} — MISSING. .claude/skills/${skill}/SKILL.md could not be read, so its checklist is not below. Do not proceed as if the standard does not exist.`;
  }
  // Skills are written as prose under headings, so the headings ARE the
  // checklist. Bold leads are used too; take whichever the file has.
  //
  // The bold pattern is /s-flagged and allows a wrapped run: `**a rule
  // that continues\non the next line**` used to match nothing, which is
  // exactly how §24.10 — "every question says what to do when it doesn't
  // apply" — never once reached a session, silently.
  const bold = [...text.matchAll(/^\*\*(.+?)\*\*/gms)].map((m) => m[1]);
  const headings = [...text.matchAll(/^#{2,3} (.+)$/gm)].map((m) => m[1]);
  const bullets = [...text.matchAll(/^- \*\*(.+?)\*\*/gms)].map((m) => m[1]);
  const rules = [...new Set([...headings, ...bold, ...bullets])]
    .map((r) => r.replace(/\s+/g, " ").replace(/[.:]$/, "").trim())
    .filter((r) => r.length > 3 && r.length < 140);
  if (rules.length === 0) {
    return `\n   ${skill} — its SKILL.md has no headings or bold rules to extract. Load it before you continue.`;
  }
  // Everything, never a slice. The old cap of nine dropped §24.8, §24.9
  // and §24.11 off the end of the surface skill without a word — a hook whose
  // whole purpose is making a standard deterministic, quietly emitting
  // two thirds of it. If a checklist is long, that is a fact about the
  // standard, not a reason to hide part of it.
  return `\n   ${skill} — its own checklist, so you do not have to load it:\n${rules
    .map((r) => `     · ${r}`)
    .join("\n")}`;
}

let payload = "";
process.stdin.on("data", (chunk) => (payload += chunk));
process.stdin.on("end", () => {
  let input;
  try {
    input = JSON.parse(payload);
  } catch {
    process.exit(0);
  }
  // Path rules below are project-relative. cwd is NOT guaranteed to be the
  // project root (the script path itself uses $CLAUDE_PROJECT_DIR); if the
  // two ever differed, every ^src/ rule silently matched nothing and this
  // hook became a no-op with exit 0 — the worst failure mode a guard has.
  const root = process.env.CLAUDE_PROJECT_DIR || process.cwd();
  // A Bash heredoc governs the same file an Edit does. Matching only
  // Edit|Write|MultiEdit let a whole slice through without one checklist
  // (2026-08-23).
  const targets = writtenPaths(input, root);
  if (targets.length === 0) process.exit(0);
  const notes = [];

  for (const rel of targets) {
    const file = rel.startsWith("/") ? rel : `${root}/${rel}`;
    const source = (() => {
      try {
        return readFileSync(file, "utf8");
      } catch {
        return "";
      }
    })();

    if (/^src\/app\/.*actions\.ts$/.test(rel) || /route\.ts$/.test(rel)) {
      notes.push(
        "Server action/route touched → SPEC §25: return typed results, never throw for expected failure." +
          checklist("error-handling"),
      );
    }
    if (/^src\/app\/.*\.tsx$/.test(rel)) {
      // A new surface gets the whole standard; an edit to an existing one
      // gets a two-line pointer. 25 bullets on a one-line import fix taught
      // sessions to skim past the block — which un-teaches the standard.
      const isNew =
        source.split("\n").length < 40 || !source.includes("export");
      notes.push(
        isNew
          ? "New surface → SPEC §23/§24 apply in full." + checklist("ui-craft")
          : "Surface edited → SPEC §23/§24: designed states, accessible names, no internal identifiers, state never colour alone. Full standard: pass 1–3 of the ui-craft skill.",
      );
    }
    if (
      /^src\/lib\/(intake|instrument|severity).*\.ts$/.test(rel) ||
      /^src\/data\/(instrument|reference)\//.test(rel)
    ) {
      // The instrument LIVES in src/data — the old rule matched only src/lib,
      // so editing gates.json or severity.json fired nothing at all (operating
      // layer audit, 2026-08-23). The content is the governed thing.
      notes.push(
        "Instrument or reference data touched → SPEC §8: bump the version string (activated versions are immutable), run `pnpm instrument:seed`, update the pinned test in the same commit, record a governance entry." +
          checklist("instrument"),
      );
    }
    if (/^\.claude\/(agents|skills)\//.test(rel)) {
      notes.push(
        "Agent or skill changed → run `pnpm agent-map` so docs/agent-map.html and the in-app transparency page match. test/unit/agent-map.test.ts fails the build until you do.",
      );
    }
    if (/^CLAUDE\.md$/.test(rel) && /— DONE/.test(source)) {
      notes.push(
        "Slice status changed → demo/readiness.md must cover it: which beat does this add or change, is it built, has a person walked it, what is the fallback if it breaks live. The stop gate refuses to finish until it does (G-44).",
      );
    }
    if (/^demo\/readiness\.md$/.test(rel)) {
      notes.push(
        "Demo readiness edited → say it to the owner in the reply, not just in the file. A beat nobody has walked is not ready, however green the tests are.",
      );
    }
    if (/^drizzle\//.test(rel)) {
      notes.push(
        "Migration touched → SPEC §26.5: append a new file, never edit an applied one, and mirror it in src/lib/schema.ts.",
      );
    }
    if (source.includes("process.env") && rel !== "src/lib/config.ts") {
      notes.push(
        "BLOCKED BY TEST: process.env outside src/lib/config.ts violates SPEC §26.3 — test/unit/architecture.test.ts will fail.",
      );
    }
    if (/^src\//.test(rel) && source.split("\n").length > 400) {
      notes.push(
        `File budget: ${rel} is ${source.split("\n").length} lines (SPEC §11 ceiling: 400 new / 800 hard).`,
      );
    }
  }

  if (notes.length) {
    // Same file touched twice in one command should not say it twice.
    console.error([...new Set(notes)].map((n) => `• ${n}`).join("\n"));
    process.exit(2); // surfaced to the model as feedback, not a failure
  }
  process.exit(0);
});

#!/usr/bin/env node
/**
 * PreToolUse guard (SPEC §15, promised since S1 and built 2026-08-23).
 *
 * The advise hook reminds AFTER an edit lands; these three are the edits
 * where after is too late. Exit 2 blocks the tool call with the reason.
 *
 * Deliberately narrow: a guard that false-blocks gets disabled, and a
 * disabled guard is worse than none (the Stop gate was deleted once).
 */
import { existsSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { writtenPaths } from "../lib/written-paths.mjs";

let payload = "";
process.stdin.on("data", (c) => (payload += c));
process.stdin.on("end", () => {
  let input;
  try {
    input = JSON.parse(payload);
  } catch {
    process.exit(0);
  }
  const root = process.env.CLAUDE_PROJECT_DIR || process.cwd();
  // Every path this call writes, whether it arrived as a file_path or
  // inside a Bash command. One tool call can touch several.
  const targets = writtenPaths(input, root);
  if (targets.length === 0) process.exit(0);

  for (const rel of targets) {
    const file = rel.startsWith("/") ? rel : `${root}/${rel}`;

    // 1. An applied migration is history, not a draft (§26.5). "Applied" is
    // approximated as "tracked by git" — a migration is committed with the
    // slice that ran it, so an untracked drizzle file is a new one being
    // written, which is exactly what IS allowed.
    if (/^drizzle\/.*\.sql$/.test(rel) && existsSync(file)) {
      let tracked = false;
      try {
        execFileSync("git", ["-C", root, "ls-files", "--error-unmatch", rel], {
          stdio: "ignore",
        });
        tracked = true;
      } catch {
        /* untracked → new file → allowed */
      }
      if (tracked) {
        console.error(
          `BLOCKED: ${rel} is an applied migration. Append a new numbered file instead (SPEC §26.5) and mirror it in src/lib/schema.ts.`,
        );
        process.exit(2);
      }
    }

    // 2. Environment files hold credentials and are gitignored by design.
    if (/(^|\/)\.env(\.|$)/.test(rel) || /(^|\/)\.env$/.test(rel)) {
      console.error(
        `BLOCKED: ${rel} is an environment file — edited by the owner, never by a session (SPEC §26.3). Say what to put in it instead.`,
      );
      process.exit(2);
    }
  }

  // 3. A settled governance entry may be compressed or superseded, never
  // silently deleted. This form only sees an Edit's replacement text; a
  // Bash rewrite of SPEC.md is caught by the Stop gate instead, which
  // compares the whole log against the last commit and so cannot be
  // walked around by choosing a different tool.
  if (targets.includes("SPEC.md") && input?.tool_input?.old_string) {
    const oldS = input.tool_input.old_string;
    const newS = input.tool_input.new_string ?? "";
    const settled = [
      ...oldS.matchAll(/\*\*(G-\d+a?) \((?:settled|superseded[^)]*)\)/g),
    ].map((m) => m[1]);
    const dropped = settled.filter((g) => !newS.includes(g));
    if (dropped.length) {
      console.error(
        `BLOCKED: this edit deletes governance entr${dropped.length === 1 ? "y" : "ies"} ${dropped.join(", ")} from SPEC §13. A settled decision is compressed or marked superseded — never removed (Build Rule 10). If superseding, keep the id and mark it.`,
      );
      process.exit(2);
    }
  }

  process.exit(0);
});

#!/usr/bin/env node
/**
 * Stop gate (SPEC §0 Build Rule 3): work does not conclude on a red build,
 * on a stale generated artifact, or on a slice that skipped its record.
 *
 * Everything here is mechanical. That is the point: three rounds of
 * independent verification found procedures that live only in a skill or a
 * prose line firing only when someone remembered — including registering a
 * slice's agentic opportunity, which fired when the owner asked. A hook
 * cannot forget, so anything that must always hold belongs here or in a
 * test, never only in a skill (G-18).
 *
 * Only tiers that need nothing external run, so the gate is fast and cannot
 * fail for environmental reasons. The full chain is `pnpm verify`.
 */
import { execSync } from "node:child_process";
import { readFileSync, existsSync, mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { doneSlices } from "../lib/slices.mjs";

const ROOT = process.cwd();
const problems = [];

// ---- 1. The build is green ------------------------------------------------
try {
  execSync("pnpm typecheck && pnpm test:unit", { stdio: "pipe", cwd: ROOT });
} catch (error) {
  const output = `${error.stdout ?? ""}${error.stderr ?? ""}`.slice(-1800);
  problems.push("typecheck or unit tests are red — finish the work or fix the break.\n" + output);
}

// ---- 2. Generated artifacts are current -----------------------------------
// A generated file nobody regenerates is a snapshot with better manners.
//
// Regenerate into a temp directory and COMPARE — never write. The old
// version regenerated in place, which meant it repaired what it was
// meant to report and left the working tree dirty by the clock. Both
// outputs are checked: the HTML page was regenerated and never compared,
// so hand-editing the transparency page passed silently
// (enforcement-layer verification, gate 1).
try {
  const scratch = mkdtempSync(join(tmpdir(), "stop-gate-"));
  const html = join(scratch, "agent-map.html");
  const data = join(scratch, "agents.json");
  execSync(`node scripts/build-agent-map.mjs ${html} ${data}`, { stdio: "pipe", cwd: ROOT });
  // The generation date moves every day by design; nothing else may.
  const strip = (t) => t.replace(/"?generated"?:?\s*"?[0-9]{4}-[0-9]{2}-[0-9]{2}"?/g, "");
  const stale = [
    ["src/data/agents.json", data],
    ["docs/agent-map.html", html],
  ].filter(([committed, fresh]) => {
    const on = readFileSync(join(ROOT, committed), "utf8");
    return strip(on) !== strip(readFileSync(fresh, "utf8"));
  });
  if (stale.length > 0) {
    problems.push(
      `${stale.map(([f]) => f).join(" and ")} ${stale.length === 1 ? "is" : "are"} stale. Run \`pnpm agent-map\`, review the diff and commit it.`,
    );
  }
} catch (error) {
  problems.push(`could not verify the agent map: ${error.message}`);
}

// ---- 3. Every finished slice carries its record ----------------------------
// Required sections WITH SUBSTANCE, not just a heading. `body.includes()`
// was satisfied by typing the heading and leaving it empty — and the whole
// reason this check exists is that "register the agentic opportunity"
// stopped happening when it relied on someone remembering. A check a
// person passes by typing four words has not fixed that
// (enforcement-layer verification, gate 2).
const REQUIRED = [
  { heading: "## Findings", what: "a Findings section", least: 80 },
  { heading: "## Not verified", what: "a Not verified section", least: 80 },
  {
    heading: "## Agentic opportunity",
    what: "an Agentic opportunity section (§21 item 6) — what was registered, or an explicit \"none, and why\"",
    least: 120,
  },
  {
    // SPEC calls the slice-verifier non-optional; until 2026-08-23 nothing
    // mechanical checked it ran. The verdict lives in the record, so the
    // record proves the run — a section a person could fake is still a
    // section a person had to consciously fake, which is the honesty line
    // every gate here draws (operating-layer audit, gap 4).
    heading: "## Verifier",
    what: "a Verifier section: the slice-verifier agent's verdict (PASS/FAIL) and what it checked",
    least: 80,
  },
];

/** What a section actually says: its body, minus placeholder italics. */
function sectionBody(document, heading) {
  const at = document.indexOf(heading);
  if (at === -1) return null;
  const rest = document.slice(at + heading.length);
  const end = rest.search(/\n## /);
  return (end === -1 ? rest : rest.slice(0, end))
    .replace(/_[^_]*_/g, "") // the skeleton's italic prompts are not content
    .replace(/\s+/g, " ")
    .trim();
}

try {
  const claude = readFileSync(join(ROOT, "CLAUDE.md"), "utf8");
  for (const slice of doneSlices(claude)) {
    const record = join(ROOT, "uat", `${slice}.md`);
    if (!existsSync(record)) {
      problems.push(`slice ${slice} is marked DONE but has no uat/${slice}.md (G-24).`);
      continue;
    }
    const body = readFileSync(record, "utf8");
    // The Verifier section is required of records verified from 2026-08-23
    // (G-55). The five earlier records predate the rule, and writing
    // verdicts into them now would fabricate history — the one thing a
    // UAT record must never do.
    const when = body.match(/^verified-on:\s*(\S+)/m)?.[1] ?? "9999";
    const applicable = REQUIRED.filter(
      (r) => r.heading !== "## Verifier" || when >= "2026-08-23",
    );
    for (const { heading, what, least } of applicable) {
      const said = sectionBody(body, heading);
      if (said === null) problems.push(`uat/${slice}.md is missing ${what}.`);
      else if (said.length < least)
        problems.push(
          `uat/${slice}.md has ${heading} but says almost nothing under it (${said.length} characters). It needs ${what}.`,
        );
    }
  }
} catch (error) {
  problems.push(`could not check slice records: ${error.message}`);
}

// ---- 4. The demo conversation has been had ------------------------------
// Build completeness is not demo readiness. This does not judge whether the
// demo is good — it refuses to let a slice finish without someone saying
// what it changed for the room (G-44).
try {
  const readiness = readFileSync(join(ROOT, "demo", "readiness.md"), "utf8");
  const claude = readFileSync(join(ROOT, "CLAUDE.md"), "utf8");
  const done = doneSlices(claude).sort();
  const covered = (readiness.match(/^slices-covered:\s*(.+)$/m)?.[1] ?? "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean)
    .sort();
  const missing = done.filter((s) => !covered.includes(s));
  if (missing.length > 0) {
    problems.push(
      `demo/readiness.md does not cover ${missing.join(", ")}. Before finishing: which beat does this slice add or change, is it built, has a person walked it, and what is the fallback if it breaks in front of the room? Update the file and say so out loud — this is the conversation, not the paperwork.`,
    );
  }
} catch (error) {
  problems.push(`could not read demo/readiness.md — the demo record is missing: ${error.message}`);
}

// ---- 5. No governance decision has disappeared ----------------------------
// The PreToolUse guard can only inspect an Edit's replacement text, so a
// SPEC rewritten through Bash slipped past it. This compares the whole log
// against the last commit and cannot be walked around by choosing a
// different tool — a decision may be compressed or marked superseded, never
// removed (Build Rule 10).
try {
  const now = readFileSync(join(ROOT, "SPEC.md"), "utf8");
  const committed = execSync("git show HEAD:SPEC.md", { cwd: ROOT, encoding: "utf8" });
  const idsIn = (text) => new Set([...text.matchAll(/\*\*(G-\d+a?) \(/g)].map((m) => m[1]));
  const before = idsIn(committed);
  const after = idsIn(now);
  const gone = [...before].filter((id) => !after.has(id));
  if (gone.length > 0) {
    problems.push(
      `SPEC §13 has lost ${gone.join(", ")} since the last commit. A settled decision is compressed or marked superseded, never removed (Build Rule 10). Restore the id, or mark it superseded and keep it.`,
    );
  }
} catch (error) {
  // No commit yet, or git unavailable: say so rather than passing quietly.
  if (!/unknown revision|does not exist/i.test(String(error.message))) {
    problems.push(`could not check the governance log against the last commit: ${error.message}`);
  }
}

// ---- 5. Stated measurements cite the test that asserts them ---------------
// "Five intake answers decided six of eleven areas" sat in the demo script
// after the instrument had moved on; the real number was four (G-50 era,
// caught 2026-08-22). A number a presenter is told to SAY is a claim the
// product makes: it must cite a test file, and the file must exist.
try {
  const readiness = readFileSync(join(ROOT, "demo", "readiness.md"), "utf8");
  const measured = [...readiness.matchAll(/measured[^|]*?—\s*see\s+`([^`]+)`/g)].map((m) => m[1]);
  const numeric = /\b(one|two|three|four|five|six|seven|eight|nine|ten|\d+) (?:of|out of) (?:one|two|three|four|five|six|seven|eight|nine|ten|eleven|\d+)\b/;
  const saysNumbers = readiness
    .split("\n")
    .filter((line) => line.startsWith("|") && numeric.test(line) && /say/i.test(line));
  for (const line of saysNumbers) {
    if (!/`[^`]*test[^`]*`/.test(line)) {
      problems.push(
        `demo/readiness.md tells the presenter to say a number without citing the test that asserts it: "${line.slice(0, 100)}…" — a stated measurement cites its test (demo-truth).`,
      );
    }
  }
  for (const cited of measured) {
    if (!existsSync(join(ROOT, cited))) {
      problems.push(`demo/readiness.md cites \`${cited}\` as the measurement's test, but the file does not exist.`);
    }
  }
} catch (error) {
  problems.push(`could not run the claim check on demo/readiness.md: ${error.message}`);
}

if (problems.length > 0) {
  console.error("Stop gate:\n- " + problems.join("\n- "));
  process.exit(2);
}
process.exit(0);
